import ast,json,pathlib,sys
errors=[]
for name in sys.argv[1:]:
 try:
  source=pathlib.Path(name).read_bytes();compile(source,name,'exec');ast.parse(source,filename=name,feature_version=(3,11))
 except SyntaxError as error: errors.append({'file':name,'line':error.lineno,'message':error.msg})
print(json.dumps({'checked':len(sys.argv)-1,'errors':errors,'minimum_grammar':'3.11','runtime':sys.version.split()[0]}))
sys.exit(bool(errors))
